/**
 * The fingering editor: the open song's finger for each note, generated by `fingerHand`, given by the
 * song's guide, and set by hand where the learner chose one.
 *
 * The learner clicks a note to select it, then presses 1 to 5 to give it that finger. 0, Backspace or
 * Delete gives the note back to the search, and Escape lets the selection go. `FingeringEditor` holds the
 * selection and the fingers, and `attachFingeringEditor` connects it to a canvas and the keys.
 *
 * Decisions, and what each costs:
 * - The search runs per hand over the notes the track hands give it, a split track at middle C. Every
 *   other note takes no generated finger, so a percussion or accompaniment track stays unmarked.
 * - A finger set by hand is a fixed finger of the search. It is never overwritten, and the generated
 *   fingers around it follow it.
 * - A song's guide may give its own fingers, which arrive after the song loads. They are fixed fingers
 *   too, under the learner's: a finger set by hand wins, and the search fills only the notes left over.
 *   They are never stored, since the guide gives them again on each load.
 * - A note is known by its track and its index among that track's notes. A song file never changes, so
 *   the key holds across sessions without storing the note itself.
 * - The fingers set by hand live in `localStorage` under `FINGERS_KEY`, by song id, beside the track
 *   settings but apart from them. Resetting a song's tracks then never erases fingering work. A song
 *   with none is not stored.
 * - The generated fingers are cached per song, hands and set fingers, and found again on the first read
 *   after any of them changes. A change of hands reaches the editor through that read alone.
 * - While a note is selected, the digit keys belong to the editor. Its key listener runs first and stops
 *   the event, so the computer keyboard plays no note and no hotkey runs on those keys.
 * - Every stored value is checked on read, and a malformed entry is dropped.
 *
 * Bounds: the cache holds one finger per note of the open song. The store holds one entry per finger set
 * by hand.
 *
 * The shell attaches the editor to the scene, which reads it for its finger labels and its selected note.
 */
import { noteChange } from "../data/changes";
import type { Note, Song } from "../midi/song";
import { handOfNote, type TrackHand } from "../input/wait-mode";
import { takesKey, type KeyPress } from "../play/hotkeys";
import type { StorageLike } from "../settings/store";
import { type Finger, fingerHand } from "./fingering";

/** The `localStorage` key of the fingers set by hand, by song id, then by note key. */
export const FINGERS_KEY = "learn-piano-easy.fingers";

/** A pointer that moves farther than this between press and release drags, in CSS pixels. */
export const CLICK_SLOP = 4;

/** The key of `note` in `song`: its track, then its index among that track's notes. */
export function noteKey(song: Song, note: Note): string {
  return `${note.track}:${song.tracks[note.track]?.notes.indexOf(note) ?? -1}`;
}

/**
 * The finger of each note of `song` that a hand plays, with `hands` giving each track's hand by index.
 * `fixed` holds the fingers set by hand, which the result keeps, whether a hand plays their note or not.
 */
export function songFingering(song: Song, hands: readonly TrackHand[], fixed: ReadonlyMap<Note, Finger>): Map<Note, Finger> {
  const out = new Map(fixed);
  for (const hand of ["right", "left"] as const) {
    const notes = song.notes.filter((note) => !song.tracks[note.track]?.percussion && handOfNote(note, hands[note.track]) === hand);
    const pinned = new Map<number, Finger>();
    notes.forEach((note, index) => {
      const finger = fixed.get(note);
      if (finger !== undefined) pinned.set(index, finger);
    });
    fingerHand(notes, hand, pinned).forEach((finger, index) => {
      if (finger !== undefined) out.set(notes[index]!, finger);
    });
  }
  return out;
}

function isFinger(value: unknown): value is Finger {
  return value === 1 || value === 2 || value === 3 || value === 4 || value === 5;
}

/** Keeps each song's fingers set by hand in `storage`, by note key. */
export class FingerStore {
  readonly #storage: StorageLike | null;
  readonly #songs: Record<string, Record<string, Finger>> = {};

  /** Reads `storage`. Null keeps everything in memory. */
  constructor(storage: StorageLike | null) {
    this.#storage = storage;
    let raw: unknown;
    try {
      raw = JSON.parse(storage?.getItem(FINGERS_KEY) ?? "null");
    } catch {
      raw = null;
    }
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return;
    for (const [id, marks] of Object.entries(raw)) {
      if (typeof marks !== "object" || marks === null) continue;
      const kept: Record<string, Finger> = {};
      for (const [key, finger] of Object.entries(marks)) if (/^\d+:\d+$/.test(key) && isFinger(finger)) kept[key] = finger;
      if (Object.keys(kept).length > 0) this.#songs[id] = kept;
    }
  }

  /** The fingers set by hand in the song `id`, by note key. */
  fingersFor(id: string): Map<string, Finger> {
    return new Map(Object.entries(this.#songs[id] ?? {}));
  }

  /** Keeps `fingers` as the song `id`'s, by note key. No fingers forget the song. */
  save(id: string, fingers: ReadonlyMap<string, Finger>): void {
    if (fingers.size === 0) delete this.#songs[id];
    else this.#songs[id] = Object.fromEntries(fingers);
    try {
      this.#storage?.setItem(FINGERS_KEY, JSON.stringify(this.#songs));
    } catch {
      return; // A storage that refuses keeps the fingers for this session only.
    }
    noteChange("fingers");
  }
}

/** The finger a digit key sets, by code, and the codes that give a note back to the search. */
const FINGER_CODES: ReadonlyMap<string, Finger> = new Map(
  ([1, 2, 3, 4, 5] as const).flatMap((finger) => [[`Digit${finger}`, finger] as const, [`Numpad${finger}`, finger] as const]),
);
const CLEAR_CODES = new Set(["Digit0", "Numpad0", "Backspace", "Delete"]);

/** The open song's fingers, the selected note, and the fingers the learner set by hand. */
export class FingeringEditor {
  readonly #store: FingerStore;
  readonly #hands: { hands(): readonly TrackHand[] };
  readonly #listeners = new Set<() => void>();
  #id = "";
  #song: Song | undefined;
  #fixed = new Map<Note, Finger>();
  #guided = new Map<Note, Finger>();
  #selected: Note | undefined;
  #cache: { hands: string; fingers: Map<Note, Finger> } | undefined;

  /** Keeps set fingers in `store`, and reads each track's hand from `hands`. */
  constructor(store: FingerStore, hands: { hands(): readonly TrackHand[] }) {
    this.#store = store;
    this.#hands = hands;
  }

  /** Takes `song`, known as `id`, with the fingers set by hand in it. */
  load(id: string, song: Song): void {
    this.#id = id;
    this.#song = song;
    this.#selected = undefined;
    this.#fixed = new Map();
    this.#guided = new Map();
    for (const [key, finger] of this.#store.fingersFor(id)) {
      const [track, index] = key.split(":").map(Number);
      const note = song.tracks[track!]?.notes[index!];
      if (note !== undefined) this.#fixed.set(note, finger);
    }
    this.#cache = undefined;
    this.#tell();
  }

  /**
   * Takes the guide's `fingers` of the song `id`, by note key, or drops them with undefined. Fingers of
   * a song no longer open are ignored.
   */
  guide(id: string, fingers: ReadonlyMap<string, Finger> | undefined): void {
    const song = this.#song;
    if (song === undefined || id !== this.#id) return;
    this.#guided = new Map();
    for (const [key, finger] of fingers ?? []) {
      const [track, index] = key.split(":").map(Number);
      const note = song.tracks[track!]?.notes[index!];
      if (note !== undefined) this.#guided.set(note, finger);
    }
    this.#cache = undefined;
    this.#tell();
  }

  /** Whether the finger of `note` comes from the song's guide, and the learner left it as it is. */
  isGuided(note: Note): boolean {
    return this.#guided.has(note) && !this.#fixed.has(note);
  }

  /** The selected note, which the digit keys give a finger, or undefined. */
  get selected(): Note | undefined {
    return this.#selected;
  }

  /** Selects `note`, or lets the selection go with undefined. */
  select(note: Note | undefined): void {
    if (note === this.#selected) return;
    this.#selected = note;
    this.#tell();
  }

  /** The finger of `note`: set by hand, generated, or undefined when no hand plays it. */
  fingerOf(note: Note): Finger | undefined {
    return this.#fingers().get(note);
  }

  /** The hand that plays `note`, from its track's hand, or undefined when no hand plays it. */
  handOf(note: Note): "right" | "left" | undefined {
    return handOfNote(note, this.#hands.hands()[note.track]);
  }

  /** Whether the learner set the finger of `note` by hand. */
  isSet(note: Note): boolean {
    return this.#fixed.has(note);
  }

  /** Sets the finger of `note` by hand, or gives it back to the search with undefined, and stores it. */
  setFinger(note: Note, finger: Finger | undefined): void {
    const song = this.#song;
    if (song === undefined || this.#fixed.get(note) === finger) return;
    if (finger === undefined) this.#fixed.delete(note);
    else this.#fixed.set(note, finger);
    this.#store.save(this.#id, new Map([...this.#fixed].map(([each, f]) => [noteKey(song, each), f])));
    this.#cache = undefined;
    this.#tell();
  }

  /**
   * Acts on `press` while a note is selected: a digit from 1 to 5 sets its finger, 0, Backspace or
   * Delete clears it, and Escape lets it go. Returns whether the press was taken.
   */
  press(press: KeyPress): boolean {
    const note = this.#selected;
    if (note === undefined || press.ctrlKey || press.altKey || press.metaKey || press.shiftKey || takesKey(press.target, press.code)) return false;
    const finger = FINGER_CODES.get(press.code);
    if (finger !== undefined) this.setFinger(note, finger);
    else if (CLEAR_CODES.has(press.code)) this.setFinger(note, undefined);
    else if (press.code === "Escape") this.select(undefined);
    else return false;
    return true;
  }

  /** Hears each change of the fingers or the selection, a load among them. Returns what stops it. */
  subscribe(listener: () => void): () => void {
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  #fingers(): Map<Note, Finger> {
    const song = this.#song;
    if (song === undefined) return this.#fixed;
    const hands = this.#hands.hands().join();
    if (this.#cache?.hands !== hands) {
      const fixed = new Map([...this.#guided, ...this.#fixed]);
      this.#cache = { hands, fingers: songFingering(song, this.#hands.hands(), fixed) };
    }
    return this.#cache.fingers;
  }

  #tell(): void {
    for (const listener of [...this.#listeners]) listener();
  }
}

/** What the editor needs of the scene: its canvas, and the note under a client point. */
export interface NotePicker {
  readonly canvas: HTMLElement;
  noteAt(x: number, y: number): Note | undefined;
}

/**
 * Selects the note the learner clicks on `picker`'s canvas, and gives `editor` the keys from `target`.
 * Call it before `attachKeyboard`, so its key listener runs first. Returns what stops it.
 */
export function attachFingeringEditor(editor: FingeringEditor, picker: NotePicker, target: Window = window): () => void {
  let down: { x: number; y: number } | undefined;
  const onDown = (event: PointerEvent) => {
    down = { x: event.clientX, y: event.clientY };
  };
  const onClick = (event: MouseEvent) => {
    const from = down;
    down = undefined;
    if (from !== undefined && Math.hypot(event.clientX - from.x, event.clientY - from.y) > CLICK_SLOP) return;
    editor.select(picker.noteAt(event.clientX, event.clientY));
  };
  const onKey = (event: KeyboardEvent) => {
    if (!editor.press(event)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  };

  picker.canvas.addEventListener("pointerdown", onDown);
  picker.canvas.addEventListener("click", onClick);
  target.addEventListener("keydown", onKey, true);
  return () => {
    picker.canvas.removeEventListener("pointerdown", onDown);
    picker.canvas.removeEventListener("click", onClick);
    target.removeEventListener("keydown", onKey, true);
  };
}
